framework_component_specs.TableOfContents:
# TableOfContents

## Purpose
Auto-collapsing article navigation in `app/articles/TableOfContents.tsx`. Displays only h2 anchors; groups h3s under their preceding h2 internally. Removes emoji from labels. Typically injected by ArticleEnhancer into ArticleTocPlaceholder.

## Props
| Prop | Type | Default | Description |
|---|---|---|---|
| `items` | `TocItem[]` | Required | Labels and anchors |
| `title` | `string` | `"Contents"` | Section title |
| `ariaLabel` | `string` | `"Table of contents"` | Accessible navigation label |
| `className` | `string` | — | Additional CSS classes |
| `activeId` | `string` | — | Controlled active section ID |
| `onItemClick` | `(id: string) => void` | — | Item-click callback |

## Working React Router implementation
Render inside the application's router. Heading IDs must match item IDs. Native disclosure provides keyboard-accessible collapsing; active sections expand automatically.

```tsx
"use client";

import { useEffect, useRef, useState } from "react";
import type { ReactElement } from "react";
import { Link } from "react-router";

export type TocItem = {
  id: string;
  label: string;
  level: 2 | 3;
  children?: TocItem[];
};

type Props = {
  items: TocItem[];
  title?: string;
  ariaLabel?: string;
  className?: string;
  activeId?: string;
  onItemClick?: (id: string) => void;
};

function cleanLabel(label: string): string {
  return label.replace(
    /[\p{Extended_Pictographic}\p{Emoji_Presentation}\uFE0F\u200D]/gu,
    "",
  ).trim();
}

export function TableOfContents({
  items, title = "Contents", ariaLabel = "Table of contents",
  className, activeId, onItemClick,
}: Props): ReactElement {
  const [observedId, setObservedId] = useState("");
  const disclosure = useRef<HTMLDetailsElement>(null);
  const groups: TocItem[] = [];
  for (const item of items) {
    if (item.level === 2) {
      groups.push({ ...item, children: [...(item.children ?? [])] });
    } else {
      groups.at(-1)?.children?.push(item);
    }
  }
  const selected = activeId ?? observedId;
  const active = groups.find((item) =>
    item.id === selected ||
    item.children?.some((child) => child.id === selected),
  );

  useEffect(() => {
    const observer = new IntersectionObserver((entries) => {
      for (const entry of entries) {
        if (entry.isIntersecting) setObservedId(entry.target.id);
      }
    }, { rootMargin: "0px 0px -65% 0px" });
    for (const item of items.flatMap((item) => [
      item, ...(item.children ?? []),
    ])) {
      const target = document.getElementById(item.id);
      if (target) observer.observe(target);
    }
    return () => observer.disconnect();
  }, [items]);

  useEffect(() => {
    if (selected && disclosure.current) disclosure.current.open = true;
  }, [selected]);

  return (
    <details ref={disclosure} open className={className}>
      <summary>{title}</summary>
      <nav aria-label={ariaLabel}>
        <ul>
          {groups.map((item) => (
            <li key={item.id}>
              <Link
                to={`#${encodeURIComponent(item.id)}`}
                preventScrollReset
                aria-current={active?.id === item.id ? "true" : undefined}
                className="text-indigo-600 no-underline aria-[current=true]:font-bold"
                onClick={() => {
                  onItemClick?.(item.id);
                  document.getElementById(item.id)?.scrollIntoView({
                    behavior: window.matchMedia("(prefers-reduced-motion: reduce)").matches
                      ? "instant" : "smooth",
                  });
                }}
              >{cleanLabel(item.label)}</Link>
            </li>
          ))}
        </ul>
      </nav>
      <span className="sr-only" role="status">
        {active ? cleanLabel(active.label) : ""}
      </span>
    </details>
  );
}
```

## Semantic hints
`toc`, `table-of-contents`, `navigation`, `outline`, `contents`, `nav`, `page-nav`, `section-nav`, `sidebar-toc`

