# ArticleCardBySlug

## Purpose
Registry-backed wrapper in `app/articles/ArticleCardBySlug.tsx`. Resolves article metadata, formats dates, resolves authors, supplies a fallback image, and renders `ArticleCard` with React Router navigation. No loader or client-only directive is needed for this synchronous lookup.

## Props
| Prop | Type | Default | Description |
|---|---|---|---|
| `slug` | `string` | Required | Article registry slug |
| `ctaText` | `string` | `"Read more"` | Call-to-action text |
| `className` | `string` | — | Additional CSS classes |
| `descriptionOverride` | `string` | — | Overrides article description |
| `variant` | `"default" \| "compact"` | `"default"` | Card size variant |
| `authorOverride` | `Author` | — | Overrides resolved author |

## Semantic Hints
`card`, `article-card`, `slug-card`, `dynamic-card`, `registry-card`, `auto-card`

## Behavior and Styling
Use when only an article slug is available. Look up metadata, resolve overrides, format the date, and render `ArticleCard`. Unknown slugs log a warning and return `null`. Invalid dates are omitted. Styling belongs to `ArticleCard`; forward classes and variant without introducing new design tokens.

## Complete React Router Example
The default export can serve as a route component inside a React Router application. Replace the sample registries with project data when integrating.

```tsx
import { Link } from "react-router";
import type { ReactElement } from "react";

type Author = { name: string };
type Article = {
  title: string;
  description: string;
  date: string;
  image?: string;
  authorId?: string;
};
type ArticleCardBySlugProps = {
  slug: string;
  ctaText?: string;
  className?: string;
  descriptionOverride?: string;
  variant?: "default" | "compact";
  authorOverride?: Author;
};
type CardProps = {
  title: string;
  description: string;
  image: string;
  date: string | null;
  author?: Author;
  to: string;
  ctaText: string;
  className?: string;
  variant: "default" | "compact";
};

const AUTHORS: Record<string, Author> = {
  editor: { name: "Editorial team" },
};
const ARTICLES: Record<string, Article> = {
  "machine-learning-basics": {
    title: "Machine Learning Basics",
    description: "An introduction to machine learning.",
    date: "2025-01-15",
    authorId: "editor",
  },
};
const FALLBACK_IMAGE =
  "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg'/%3E";

function formatDate(value: string): string | null {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return null;
  return date.toLocaleDateString("en-US", { timeZone: "UTC" });
}

function ArticleCard(props: CardProps): ReactElement {
  return (
    <article className={props.className} data-variant={props.variant}>
      <img src={props.image} alt="" />
      <h2>{props.title}</h2>
      <p>{props.description}</p>
      <p>{props.author?.name}</p>
      <p>{props.date}</p>
      <Link to={props.to}>{props.ctaText}</Link>
    </article>
  );
}

export function ArticleCardBySlug({
  slug,
  ctaText = "Read more",
  className,
  descriptionOverride,
  variant = "default",
  authorOverride,
}: ArticleCardBySlugProps): ReactElement | null {
  const article = ARTICLES[slug];
  if (!article) {
    console.warn("Unknown article slug:", slug);
    return null;
  }
  return (
    <ArticleCard
      title={article.title}
      description={descriptionOverride ?? article.description}
      image={article.image || FALLBACK_IMAGE}
      date={formatDate(article.date)}
      author={authorOverride ?? AUTHORS[article.authorId ?? ""]}
      to={`/articles/${encodeURIComponent(slug)}`}
      ctaText={ctaText}
      className={className}
      variant={variant}
    />
  );
}

export default function ArticleExample(): ReactElement {
  return <ArticleCardBySlug slug="machine-learning-basics" />;
}
```

