# ArticleCompanyHighlightCTA

`app/articles/ArticleCompanyHighlightCTA.tsx`

Prominent product/feature CTA with content and actions beside an image. Use when more visual impact than ArticleCompanyCTA is needed.

## Props

| Prop | Type | Default | Description |
|---|---|---|---|
| `title` | `string` | Required | CTA heading |
| `body` | `string` | Required | CTA description |
| `primaryButton` | `ButtonProps` | Required | Primary action |
| `image` | `string` | Required | Product/feature image URL |
| `label` | `string` | — | Small label above title |
| `secondaryButton` | `ButtonProps` | — | Secondary action |
| `note` | `string` | — | Small note text |
| `id` | `string` | — | Section anchor ID |
| `className` | `string` | — | Additional CSS classes |
| `imageAlt` | `string` | `title` | Meaningful image alternative |
| `imagePosition` | `"left" \| "right"` | `"right"` | Image position |

## Implementation

Use React Router `Link` for application destinations and native anchors for external URLs. No client directive is needed: this component has no browser-only integration.

```tsx
import { Link } from "react-router";
import type { ReactElement } from "react";

type ButtonProps = {
  text: string;
  href: string;
  variant?: "primary" | "secondary" | "outline";
};

type ArticleCompanyHighlightCTAProps = {
  title: string;
  body: string;
  primaryButton: ButtonProps;
  image: string;
  label?: string;
  secondaryButton?: ButtonProps;
  note?: string;
  id?: string;
  className?: string;
  imageAlt?: string;
  imagePosition?: "left" | "right";
};

function renderButton(
  button: ButtonProps,
  fallback: "primary" | "secondary",
): ReactElement {
  const variant = button.variant ?? fallback;
  if (/^(?:[a-z][a-z\d+.-]*:|\/\/)/i.test(button.href)) {
    return (
      <a href={button.href} data-variant={variant}>
        {button.text}
      </a>
    );
  }
  return (
    <Link to={button.href} data-variant={variant}>
      {button.text}
    </Link>
  );
}

export function ArticleCompanyHighlightCTA({
  title, body, primaryButton, image, label, secondaryButton,
  note, id, className, imageAlt = title, imagePosition = "right",
}: ArticleCompanyHighlightCTAProps): ReactElement {
  const picture = (
    <div>
      <img src={image} alt={imageAlt} style={{ maxWidth: "100%" }} />
    </div>
  );
  return (
    <section id={id} className={className} aria-label={title}>
      <div data-image-position={imagePosition}>
        {imagePosition === "left" && picture}
        <div>
          {label && <span>{label}</span>}
          <h2>{title}</h2>
          <p>{body}</p>
          <div>
            {renderButton(primaryButton, "primary")}
            {secondaryButton && renderButton(secondaryButton, "secondary")}
          </div>
          {note && <p>{note}</p>}
        </div>
        {imagePosition === "right" && picture}
      </div>
    </section>
  );
}

export default function ExampleRoute(): ReactElement {
  return (
    <ArticleCompanyHighlightCTA
      label="New Feature"
      title="AI-Powered Analytics"
      body="Discover real-time insights and predictions."
      primaryButton={{ text: "Start Free Trial", href: "/trial" }}
      secondaryButton={{
        text: "Watch Demo",
        href: "/demo",
        variant: "outline",
      }}
      image="/images/analytics-dashboard.png"
      imageAlt="Analytics dashboard showing real-time predictions"
      note="No credit card required"
    />
  );
}
```

## Styling and accessibility

Apply project styles: white background, subtle border, rounded container/image; equal desktop columns stacked on mobile. Preserve image order when stacking. Use small uppercase brand-colored labels, large bold headings, adjacent actions, and a stronger primary action. Contain or crop images appropriately. Ensure visible link focus and sufficient contrast; reuse established tokens.

## Semantic hints

`cta`, `highlight-cta`, `featured-cta`, `accent-cta`, `product-cta`, `demo-cta`, `showcase-cta`

